import json
from html import escape as e
from pathlib import Path
root=Path(__file__).parent
refs=json.loads((root/'references.json').read_text())
cards=[]
for i,r in enumerate(refs,1):
    images=''.join(f'<a href="{e(r["url"],quote=True)}" target="_blank" rel="noreferrer"><img src="{e(s,quote=True)}" alt="{e(r["name"])} 参考原作" loading="eager"><span class="loading">图片加载中</span></a>' for s in [r['image'],r.get('image2')] if s)
    pin=f'<a href="{e(r["pin"],quote=True)}" target="_blank" rel="noreferrer">Pinterest 原 Pin ↗</a>' if r.get('pin') else ''
    cards.append(f'''<article class="card" data-group="{r['group']}" id="{r['id']}"><div class="media">{images}</div><div class="body"><div class="meta">{i:02} / {r['kind']}</div><h2>{r['name']}</h2><p class="fact">{r['fact']}</p><p class="judgment">{r['judgment']}</p><p class="boundary">取舍：{r['boundary']}</p><div class="links"><a href="{e(r['url'],quote=True)}" target="_blank" rel="noreferrer">原作者 / 原项目 ↗</a>{pin}</div><details><summary>核验范围</summary><p>{r['verified']}</p></details></div></article>''')
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TokenMini · 第二轮视觉研究</title><style>
:root{font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;color:#151714;background:#f0f0e9;font-size:16px}*{box-sizing:border-box}body{margin:0}main{max-width:1600px;padding:30px 32px 72px;margin:auto}a{color:inherit;text-underline-offset:4px}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #416cff;outline-offset:4px}.top{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid #bfc4ba;padding-bottom:18px;font-size:12px;letter-spacing:.08em}.hero{padding:48px 0 30px;max-width:1000px}h1{font-size:clamp(34px,5vw,68px);font-weight:550;line-height:1.16;letter-spacing:-.045em;margin:0 0 25px}.intro{font-size:19px;max-width:860px;line-height:1.8}.status{font-size:14px;padding:14px 16px;background:#e7dccc;border-left:3px solid #6e442b;line-height:1.7}.rules{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin:16px 0 32px}.rules div{border-top:2px solid #161d18;padding-top:16px}.rules h3{font-size:19px;margin:0 0 8px}.rules p{font-size:14px;color:#4e574f;line-height:1.8;margin:0}.filters{display:flex;flex-wrap:wrap;gap:10px;padding:15px 0 24px}button{border:1px solid #bfc4ba;border-radius:28px;background:none;padding:9px 16px;font:inherit;font-size:14px;cursor:pointer}button[aria-pressed=true]{color:white;background:#222b25}.count{margin:auto 0 auto auto;font-size:13px;color:#535c54}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:30px;align-items:start}.card{border:1px solid #ccd0c7;background:#fafaf6;min-width:0}.card[hidden]{display:none}.media{background:#e5e6df;display:flex;flex-wrap:wrap;gap:1px;min-width:0}.media a{display:block;flex:1 1 220px;min-width:0;position:relative;height:370px;background:#e9eae4}.media img{display:block;object-fit:contain;width:100%;height:100%}.loading{position:absolute;bottom:8px;left:10px;font-size:11px;background:#0009;color:white;border-radius:3px;padding:4px 8px}.media a.loaded .loading{display:none}.body{padding:24px}.meta{font-size:12px;color:#65715f}h2{font-size:25px;margin:9px 0 15px;font-weight:550;letter-spacing:-.025em}.body p{line-height:1.8;font-size:15px;margin:14px 0}.fact{color:#656d63}.judgment{font-weight:500}.boundary{font-size:13px!important;color:#656d63}.links{display:flex;flex-wrap:wrap;gap:16px;font-size:13px;margin:24px 0 15px}details{font-size:12px;color:#656d63}summary{cursor:pointer}details p{font-size:12px!important}.decision{border-top:1px solid #bfc4ba;margin-top:44px;padding-top:26px}.decision h2{font-size:30px}.decision p{font-size:16px;line-height:1.9;max-width:950px}.rejects{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.rejects p{font-size:14px}.tag{display:inline-block;background:#dce1d7;font-size:12px;padding:3px 9px}.footer{margin-top:32px;border-top:1px solid #bfc4ba;padding-top:22px;font-size:13px;color:#656d63;line-height:1.9}@media(max-width:720px){main{padding:22px 16px 48px}.hero{padding:32px 0 22px}.grid,.rules,.rejects{grid-template-columns:1fr}.intro{font-size:17px}.count{margin-left:0;width:100%}.media a{height:330px}.body{padding:21px}}
</style><main><div class="top"><span>TOKENMINI / VISUAL RESET 02</span><span>2026.09.20 · 参考研究</span></div><header class="hero"><h1>先换掉造型的出发点。</h1><p class="intro">从 Pinterest 图墙向 Behance 和原作者追溯，重新看字形、空间、信号与比例。这一页都是参考原作，尚未生成新 Logo。</p><p class="status">上一轮 A / B / C 已被用户全部否决，包括此前推荐的 C。旧稿只作失败记录，不再沿其中任何一稿深化。</p></header><section class="rules"><div><h3>放开圆形与藏 T</h3><p>环形、字母和绿色是曾讨论的元素，不再绑成每稿都必须满足的公式。先探索完全不同的轮廓。</p></div><div><h3>看图形，也看字标</h3><p>TokenMini 的定制字形可以成为核心，独立符号不必先占据全部注意力。控制比例、端点、开口和字距。</p></div><div><h3>精确与陌生感并存</h3><p>允许少量有张力的切面与不对称，避开肥厚分瓣、普通旋涡、标准 T 挖空和无意义的尖角。</p></div></section><nav class="filters" aria-label="参考分类"><button data-filter="all" aria-pressed="true">全部参考</button><button data-filter="字形与比例" aria-pressed="false">字形与比例</button><button data-filter="空间与切面" aria-pressed="false">空间与切面</button><button data-filter="信号与变化" aria-pressed="false">信号与变化</button><span class="count" aria-live="polite">7 组参考</span></nav><section class="grid">'''+''.join(cards)+'''</section><section class="decision"><span class="tag">新的设计判断</span><h2>下一轮值得探索的三个起点</h2><p><strong>字标主导：</strong>先研究 TokenMini 的整体字形、字距和局部连接，再从同一规则产生小符号。目标是精确而有个性的工具品牌。</p><p><strong>空间截面：</strong>从一个有体积、有开口的物体出发，研究它的二维投影。造型允许不圆，也不强迫看出 T。目标是像一件精密的小型仪器。</p><p><strong>信号采样：</strong>只选“采样、累积、压缩”中的一个动作，用少量线面与留白表达。目标是轻、清楚、有节奏，避免变成完整仪表盘。</p><p>这三条路线表达不同的设计起点，尚未获得用户认可。银色、玻璃、绿色可在选定结构后再回到材质探索；本轮不把它们作为造型优劣的依据。</p></section><section class="decision"><h2>这次明确排除什么</h2><div class="rejects"><div><h3>像上一轮的分瓣圆饼</h3><p>黑色大体块＋有机分瓣＋标准 T 留白，容易变成通用商标模板。三稿之间缺少真正的骨架差异。</p></div><div><h3>只靠“未来感”标签</h3><p>Pinterest 的 futuristic 搜索出现大量霓虹、科幻字体与镀铬展示。它们可能是材质灵感，不能据此判断 Logo 是否有原创性。</p></div><div><h3>把系统图案当成 Logo</h3><p>上面的符号表、网格和动态案例各有用途。复杂的辅助图形不等于可缩小的主标志；已在每张卡片上注明类型。</p></div></div></section><footer class="footer"><p>研究范围：实际浏览 Pinterest 的 experimental brand identity、experimental symbol logo、futuristic brand identity、generative visual identity 四组结果；继续核对原 Pin、Behance 公开项目与原作者说明。未保存到用户 Pinterest 图板、未联系作者。</p><p>外部原图通过原网址加载，需要联网；点击图片或原作链接可继续查看。Pinterest 的时间与作者不明确时，不当作最新发布或已商用的证明。2018 年的字形练习仅作方法对照。</p><p>Behance 浏览器入口跳到 Adobe 认证页，读取该认证页被自动审批拒绝；未继续访问认证信息。公开项目页、Pinterest 和原作者资料用于补足研究。<a href="research.md">阅读完整研究记录</a>。</p></footer></main><script>document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let n=0;document.querySelectorAll('.card').forEach(x=>{x.hidden=b.dataset.filter!=='all'&&b.dataset.filter!==x.dataset.group;if(!x.hidden)n++});document.querySelector('.count').textContent=n+' 组参考'}));document.querySelectorAll('.media img').forEach(i=>{const update=()=>{const ok=i.complete&&i.naturalWidth>0;i.parentElement.classList.toggle('loaded',ok);if(!ok)i.nextElementSibling.textContent='原图未载入，请点原作链接'};i.addEventListener('load',update);i.addEventListener('error',update);if(i.complete)update()});</script></html>'''
(root/'index.html').write_text(html)
print('built reset-v2/index.html')
